14	function CopyInline({ text }: { text: string }) {
15	  const [copied, setCopied] = useState(false);
16	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
17	
18	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
19	
20	  const handleCopy = async () => {
21	    if (timerRef.current) clearTimeout(timerRef.current);
22	    try { await navigator.clipboard.writeText(text); } catch { /* fallback */ }
23	    setCopied(true);
24	    timerRef.current = setTimeout(() => setCopied(false), 2000);
25	  };
26	  return (
27	    <button
28	      onClick={handleCopy}
29	      className={cn(
30	        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
31	        copied
32	          ? "bg-green-50 text-green-600 border-green-200"
33	          : "bg-card text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground"
34	      )}
35	    >
36	      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
37	    </button>
38	  );
