128	        </div>
129	
130	        {expanded && (
131	          <div className="mt-4 space-y-4 animate-fade-in">
132	            {/* Current state */}
133	            <div>
134	              <p className="mb-1.5 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
