151	
152	            {/* AI Suggestion */}
153	            {finding.ai_suggestion && (
154	              <div className="relative rounded-xl border border-indigo-100/80 bg-indigo-50 p-3.5">
155	                <div className="mb-1.5 flex items-center justify-between">
156	                  <div className="flex items-center gap-1.5">
157	                    <Sparkles className="h-3.5 w-3.5 text-indigo-600" />
158	                    <p className="text-xs font-semibold uppercase tracking-widest text-indigo-700">
159	                      AI Suggestion
160	                    </p>
161	                  </div>
162	                  {isPaidUser && <CopyInline text={finding.ai_suggestion} />}
163	                </div>
164	                {isPaidUser ? (
165	                  <p className="text-sm text-slate-700 leading-relaxed whitespace-pre-line">
