208	                    size="sm"
209	                    onClick={() => onToggleFixed(finding.id, true)}
210	                    className="h-8 rounded-lg bg-green-600 px-3 text-xs font-medium text-white hover:bg-green-700"
211	                  >
212	                    <CheckCircle2 className="mr-1.5 h-3.5 w-3.5" />
213	                    Fixed
214	                  </Button>
215	                ) : (
216	                  <Button
217	                    size="sm"
218	                    variant="outline"
219	                    onClick={() => onToggleFixed(finding.id, false)}
220	                    className="h-8 rounded-lg border-border/50 px-3 text-xs font-medium text-muted-foreground hover:border-green-500 hover:text-green-700"
221	                  >
222	                    <CheckCircle2 className="mr-1.5 h-3.5 w-3.5" />
223	                    Mark as Fixed
224	                  </Button>
225	                )}
226	              </div>
227	            )}
228	          </div>
229	        )}
230	      </CardContent>
231	    </Card>
232	  );
233	
234	  if (finding.is_premium) {
235	    return <PremiumLock>{content}</PremiumLock>;
236	  }
237	
238	  return content;
239	}
