1	import { useState, useEffect, useCallback, useId } from "react";
2	import { useNavigate, useSearchParams } from "react-router-dom";
3	import {
4	  ScanLine,
5	  Info,
6	  AlertCircle,
7	  Loader2,
8	  Globe,
9	  Layers,
10	} from "lucide-react";
11	import { Card, CardContent } from "@/components/ui/card";
12	import { Button } from "@/components/ui/button";
13	import { Input } from "@/components/ui/input";
14	import { Progress } from "@/components/ui/progress";
15	import {
16	  Select,
17	  SelectContent,
18	  SelectItem,
19	  SelectTrigger,
20	  SelectValue,
21	} from "@/components/ui/select";
22	import { ScanProgressTimeline } from "@/components/shared/ScanProgressTimeline";
23	import { BrowserFrame } from "@/components/shared/BrowserFrame";
24	import { PageTransition } from "@/components/shared/PageTransition";
25	import { ScanGateWall } from "@/components/shared/ScanGateWall";
26	import { CRO_PILLARS, SCAN_STEPS, PAGE_TYPES } from "@/lib/constants";
27	import { useAuth } from "@/contexts/AuthContext";
28	import { useCreateScan } from "@/hooks/use-scans";
29	import { useScan } from "@/hooks/use-scans";
30	import { useFeatureFlag } from "@/hooks/use-feature-flag";
31	import { BulkScanDialog } from "@/components/scan/BulkScanDialog";
32	import { toast } from "sonner";
33	import type { PageType } from "@/types";
34	import { isGrowthPlus } from "@/types";
35	import { cn } from "@/lib/utils";
36	
37	/** Generate a stable teaser score 45–72 for an unauthenticated guest scan */
38	function generateTeaserScore(url: string): number {
39	  let hash = 0;
40	  for (let i = 0; i < url.length; i++) {
41	    hash = (hash * 31 + url.charCodeAt(i)) & 0xffffffff;
42	  }
43	  return 45 + (Math.abs(hash) % 28);
44	}
45	
46	/** Basic URL validation — checks structure, not reachability */
47	function isValidUrl(str: string): boolean {
48	  try {
49	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
50	    return url.protocol === "https:" || url.protocol === "http:";
51	  } catch {
52	    return false;
53	  }
54	}
55	
56	/** Normalize URL: prepend https:// if missing */
57	function normalizeUrl(str: string): string {
58	  const trimmed = str.trim();
59	  if (!trimmed) return trimmed;
60	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
61	  return `https://${trimmed}`;
62	}
63	
64	// ── Map scan status to step index ───────────────────────────────
65	
66	function statusToStep(status: string): number {
67	  switch (status) {
68	    case "pending": return 0;
69	    case "analyzing": return 3;
70	    case "completed": return SCAN_STEPS.length;
71	    case "failed": return -1;
72	    default: return 0;
73	  }
74	}
75	
76	const Scan = () => {
77	  const navigate = useNavigate();
78	  const [searchParams] = useSearchParams();
79	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
80	  const [pageType, setPageType] = useState<PageType>(
81	    (searchParams.get("type") as PageType) || "landing"
82	  );
83	  const [urlError, setUrlError] = useState<string | null>(null);
84	
85	  // activeScanId drives the polling query (authenticated users only)
86	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
87	  const [simulatedStep, setSimulatedStep] = useState(-1);
88	  const [scanFailed, setScanFailed] = useState(false);
89	
90	  // Guest flow: simulate the animation then show gate wall
91	  const [guestAnimating, setGuestAnimating] = useState(false);
92	  const [guestAnimationDone, setGuestAnimationDone] = useState(false);
93	  const [guestTeaserScore, setGuestTeaserScore] = useState(0);
94	
95	  const [bulkDialogOpen, setBulkDialogOpen] = useState(false);
96	
97	  const inputId = useId();
98	  const { user, profile } = useAuth();
99	  const isAuthenticated = !!user;
100	  const freeScanEnabled = useFeatureFlag("free_scan_enabled", true);
101	  const createScan = useCreateScan();
102	
103	  const canUseBulk = isAuthenticated && isGrowthPlus(profile?.plan ?? "free");
104	
105	  const scansUsed = profile?.scans_used ?? 0;
106	  const scanLimit = profile?.scan_limit ?? 3;
107	  const scansRemaining = scanLimit - scansUsed;
108	  const atLimit = scansRemaining <= 0;
109	
110	  // Poll the scan row while it's pending/analyzing
111	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
112	    refetchInterval: activeScanId ? 2000 : false,
113	  });
114	
115	  const isAnalyzing = activeScanId !== null || guestAnimating;
116	  const normalizedUrl = normalizeUrl(rawUrl);
117	
118	  const totalSteps = SCAN_STEPS.length;
119	  const currentStep = isAnalyzing
120	    ? pollingScan
121	      ? statusToStep(pollingScan.status)
122	      : simulatedStep
123	    : -1;
124	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
125	
126	  // When polling finds a completed/failed scan, navigate or show error
127	  useEffect(() => {
128	    if (!pollingScan) return;
129	    if (pollingScan.status === "completed") {
130	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
131	    } else if (pollingScan.status === "failed") {
132	      setActiveScanId(null);
133	      setSimulatedStep(-1);
134	      setScanFailed(true);
135	    }
136	    // eslint-disable-next-line react-hooks/exhaustive-deps
137	  }, [pollingScan?.status]);
138	
139	  // Simulate step progression while waiting for the edge function (authenticated)
140	  useEffect(() => {
141	    if (!isAnalyzing || !activeScanId) return;
142	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
143	    if (simulatedStep >= totalSteps - 1) return;
144	
145	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
146	    const timer = setTimeout(
147	      () => setSimulatedStep((prev) => prev + 1),
148	      durations[simulatedStep] ?? 1200
149	    );
150	    return () => clearTimeout(timer);
151	    // totalSteps is derived from a constant — safe to omit
152	    // eslint-disable-next-line react-hooks/exhaustive-deps
153	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
154	
155	  // Guest simulated step progression — no API call, just animation
156	  useEffect(() => {
157	    if (!guestAnimating || guestAnimationDone) return;
158	    if (simulatedStep >= totalSteps - 1) {
159	      // Animation finished — show gate wall
160	      const timer = setTimeout(() => {
161	        setGuestAnimationDone(true);
162	        setGuestAnimating(false);
163	      }, 800);
164	      return () => clearTimeout(timer);
165	    }
166	
167	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
168	    const timer = setTimeout(
169	      () => setSimulatedStep((prev) => prev + 1),
170	      durations[simulatedStep] ?? 1200
171	    );
172	    return () => clearTimeout(timer);
173	    // eslint-disable-next-line react-hooks/exhaustive-deps
174	  }, [guestAnimating, guestAnimationDone, simulatedStep]);
175	
176	  const startAnalysis = useCallback(() => {
177	    setUrlError(null);
178	    if (!rawUrl.trim()) {
179	      setUrlError("Please enter a URL.");
180	      return;
181	    }
182	    if (!isValidUrl(normalizedUrl)) {
183	      setUrlError("Enter a valid URL like https://example.com/page");
184	      return;
185	    }
186	
187	    // Unauthenticated users: if free scan disabled, redirect to signup immediately
188	    if (!isAuthenticated) {
189	      if (!freeScanEnabled) {
190	        navigate("/signup");
191	        return;
192	      }
193	      setGuestAnimating(true);
194	      setGuestAnimationDone(false);
195	      setGuestTeaserScore(generateTeaserScore(normalizedUrl));
196	      setSimulatedStep(0);
197	      return;
198	    }
199	
200	    if (atLimit) return;
201	
202	    setSimulatedStep(0);
203	
204	    createScan.mutate(
205	      { url: normalizedUrl, page_type: pageType },
206	      {
207	        onSuccess: (scan) => {
208	          setActiveScanId(scan.id);
