46	
47	export function AppSidebar() {
48	  const { state } = useSidebar();
49	  const collapsed = state === "collapsed";
50	  const location = useLocation();
51	  const { profile } = useAuth();
52	  const { data: teams } = useTeams();
53	  const showTeamSwitcher = !collapsed && profile && isProPlus(profile.plan) && (teams?.length ?? 0) >= 0;
54	
55	  const integrationsEnabled = useFeatureFlag("integrations_enabled", true);
56	
57	  const navItems = BASE_NAV_ITEMS.filter((item) => {
58	    if (item.flagKey === "integrations_enabled") return integrationsEnabled;
59	    if (item.proOnly && profile) return isProPlus(profile.plan);
60	    return true;
61	  });
62	
63	  const scansUsed = profile?.scans_used ?? 0;
64	  const scanLimit = profile?.scan_limit ?? 3;
65	  const usagePercent = Math.round((scansUsed / scanLimit) * 100);
66	
67	  const isActive = (path: string) =>
68	    location.pathname === path || location.pathname.startsWith(path + "/");
69	
70	  return (
71	    <Sidebar collapsible="icon" className="border-r-0">
72	      <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
73	        <Link to="/dashboard" className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full">
74	          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
75	            <ScanLine className="h-3.5 w-3.5 text-white" />
76	          </div>
77	          {!collapsed && (
78	            <span className="text-base font-semibold tracking-tight text-white">
79	              ConvertScan
80	            </span>
81	          )}
82	        </Link>
83	        {showTeamSwitcher && (
84	          <div className="mt-3 -mx-1">
85	            <TeamSwitcher />
86	          </div>
87	        )}
88	      </SidebarHeader>
89	
90	      <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
91	        <SidebarGroup>
92	          <SidebarGroupContent>
93	            <SidebarMenu className="space-y-0.5">
94	              {navItems.map((item) => {
95	                const active = isActive(item.url);
96	                return (
97	                  <SidebarMenuItem key={item.title}>
98	                    <SidebarMenuButton
99	                      asChild
100	                      tooltip={item.title}
101	                      isActive={active}
102	                      className={cn(
103	                        "h-10 transition-colors duration-150 relative",
104	                        active
105	                          ? "bg-white/10 text-white before:absolute before:left-0 before:top-2 before:bottom-2 before:w-[2px] before:rounded-full before:bg-primary"
106	                          : "text-sidebar-foreground hover:bg-white/5 hover:text-white/80"
107	                      )}
108	                    >
109	                      <NavLink to={item.url} activeClassName="">
110	                        <item.icon className={cn(
111	                          "h-[18px] w-[18px] shrink-0",
112	                          active ? "text-white" : "text-white/55"
113	                        )} />
114	                        <span className="text-sm font-medium">{item.title}</span>
115	                      </NavLink>
116	                    </SidebarMenuButton>
117	                  </SidebarMenuItem>
118	                );
119	              })}
120	            </SidebarMenu>
121	          </SidebarGroupContent>
122	        </SidebarGroup>
123	      </SidebarContent>
124	
125	      <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
126	        {/* Scan usage indicator — expanded only */}
127	        {!collapsed && (
128	          <div className="mb-3 rounded-lg bg-white/5 p-3">
129	            <div className="flex items-center justify-between mb-1.5">
130	              <span className="text-xs text-white/40">Scans used</span>
131	              <span className="text-xs font-medium text-white/70 tabular-nums">
132	                {profile ? `${scansUsed}/${scanLimit}` : "\u2014"}
133	              </span>
134	            </div>
135	            <Progress value={profile ? usagePercent : 0} className="h-1" />
136	            <div className="mt-1.5">
137	              <Badge
138	                variant="outline"
139	                className="border-white/10 bg-transparent text-2xs text-white/40 capitalize px-1.5 py-0"
140	              >
141	                {profile?.plan ?? "free"} plan
142	              </Badge>
143	            </div>
144	          </div>
145	        )}
146	
147	        {/* Separator — hidden when collapsed (nothing above it) */}
148	        {!collapsed && <Separator className="mb-3 bg-white/5" />}
149	
150	        {profile?.plan !== "agency" && profile?.plan !== "pro" && (
151	          !collapsed ? (
152	            <Link
153	              to="/pricing"
154	              className="flex items-center justify-center gap-2 rounded-lg bg-sidebar-primary px-4 py-2.5 text-sm font-semibold text-white transition-all hover:opacity-90 hover:shadow-lg hover:shadow-sidebar-primary/20"
155	            >
156	              <Zap className="h-4 w-4" />
157	              Upgrade Plan
158	            </Link>
159	          ) : (
160	            <Link
161	              to="/pricing"
162	              aria-label="Upgrade Plan"
163	              className="flex h-9 w-9 items-center justify-center rounded-lg bg-sidebar-primary text-white transition-opacity hover:opacity-90"
164	            >
165	              <Zap className="h-4 w-4" />
166	            </Link>
167	          )
168	        )}
169	      </SidebarFooter>
170	    </Sidebar>
171	  );
172	}
